    requires K.Valid(m) && v >= 0 && w >= 0 && k != j
    ensures K.Valid(m[k := v][j := w]) && K.FrameTwo(m, m[k := v][j := w], k, j)
    ensures m[k := v][j := w][k] == v && m[k := v][j := w][j] == w
  {
    S1.Update(m, k, v);
    S2.Preserve(m, k, v);
    End.Finish(m, k, v);
    S1.Update(m[k := v], j, w);
    S2.Preserve(m[k := v], j, w);
